\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Sourdough Starter: Daily Feeding Schedule}
\author{}
\date{}

\begin{document}
\maketitle

\section*{Morning}
\begin{enumerate}
\item Weigh out 50 g of ripe starter into a clean jar.
\item Add 50 g of bread flour and 50 g of lukewarm water.
\item Stir until no dry flour remains.
\item Cover loosely and leave at room temperature.
\end{enumerate}

The starter should double within six to eight hours. If the
kitchen is cooler than 20 degrees, allow extra time before
the evening feeding; a rubber band around the jar makes the
rise easy to track.

\section*{Evening}
\begin{enumerate}
\item Discard all but 50 g of the starter.
\item Add 50 g of bread flour and 50 g of lukewarm water.
\item Stir, cover loosely, and leave overnight.
\end{enumerate}

\section*{Notes}
The schedule repeats daily. A healthy starter smells fruity
and shows bubbles on the surface and along the sides of the
jar. If a grey liquid collects on top, pour it off and feed
twice daily for a few days.
\end{document}

